    /**
     * Initializes a new MIDI Synthesizer engine.
     * @param sampleRate The sample rate of the synthesizer, in Hertz.
     * @param opts Additional options when initializing the synthesizer.
     */
    public constructor(
        sampleRate: number,
        opts: Partial<SynthProcessorOptions> = {}
    ) {
        const options = fillWithDefaults(opts, DEFAULT_SYNTH_OPTIONS);
        if (
            !Number.isFinite(options.initialTime) ||
            !Number.isFinite(sampleRate)
        ) {
            throw new TypeError(
                `Initial time or sample rate is invalid! initial time: ${options.initialTime}, sample rate: ${sampleRate}`
            );
        }
        this.sampleRate = sampleRate;
        this.sampleTime = 1 / sampleRate;
        this.currentTime = options.initialTime;
        // Replace the stubs with bound functions for less overhead
        this.lockMIDIParameter = lockMIDIParameterInternal.bind(this);
        this.setSystemParameter = setSystemParameterInternal.bind(this);
        this.setMIDIParameter = setMIDIParameterInternal.bind(this);

        this.setSystemParameter("effectsEnabled", options.effectsEnabled);
        this.setSystemParameter("eventsEnabled", options.eventsEnabled);
        this.maxBufferSize = options.maxBufferSize;

        // For GS user drum set
        this.soundBankManager.systemGetter = () => this.midiParameters.system;
        // These smoothing factors were tested on 44,100 Hz, adjust them to target sample rate here
        // Volume  smoothing factor
        this.gainSmoothingFactor =
            GAIN_SMOOTHING_FACTOR * (44_100 / sampleRate);
        // Pan smoothing factor
        this.panSmoothingFactor = PAN_SMOOTHING_FACTOR * (44_100 / sampleRate);

        const bufSize = this.maxBufferSize;
        // Initialize effects
        this.gsReverbProcessor =
            options.gsReverbProcessor ??
            new DefaultGSReverb(sampleRate, bufSize);
        this.gsChorusProcessor =
            options.gsChorusProcessor ??
            new DefaultGSChorus(sampleRate, bufSize);
        this.gsDelayProcessor =
            options.gsDelayProcessor ?? new DefaultGSDelay(sampleRate, bufSize);

        this.xgReverbBlock =
            options.xgReverbBlock ?? new DefaultXGReverb(sampleRate, bufSize);
        this.xgChorusBlock =
            options.xgChorusBlock ?? new DefaultXGChorus(sampleRate, bufSize);
        this.xgVariationBlock =
            options.xgVariationBlock ??
            new DefaultXGVariation(sampleRate, bufSize);
        this.xgInsertionBlocks =
            options.xgInsertionBlocks ??
            Array.from(
                { length: XG_INSERTION_COUNT },
                () => new DefaultXGInsertion(sampleRate, bufSize)
            );

        // Initialize buffers
        this.voiceBuffer = new Float64Array(bufSize);
        this.sharedVoiceSendBuffer = new VoiceSendBuffer(bufSize);
        this.insertionInputL = new Float32Array(bufSize);
        this.insertionInputR = new Float32Array(bufSize);
        this.gsReverbInput = new Float32Array(bufSize);
        this.gsChorusInput = new Float32Array(bufSize);
        this.gsDelayInput = new Float32Array(bufSize);
        this.xgReverbInputL = new Float32Array(bufSize);
        this.xgReverbInputR = new Float32Array(bufSize);
        this.xgChorusInputL = new Float32Array(bufSize);
        this.xgChorusInputR = new Float32Array(bufSize);
        this.xgVariationInputL = new Float32Array(bufSize);
        this.xgVariationInputR = new Float32Array(bufSize);
        this.gsReverbSend = new Float64Array(bufSize);
        this.gsChorusSend = new Float64Array(bufSize);
        this.gsDelaySend = new Float64Array(bufSize);
        this.xgReverbSendL = new Float64Array(bufSize);
        this.xgReverbSendR = new Float64Array(bufSize);
        this.xgChorusSendL = new Float64Array(bufSize);
        this.xgChorusSendR = new Float64Array(bufSize);
        this.xgVariationSendL = new Float64Array(bufSize);
        this.xgVariationSendR = new Float64Array(bufSize);
        this.xgInsertionBufferL = new Float32Array(bufSize);
        this.xgInsertionBufferR = new Float32Array(bufSize);

        // Register insertion
        for (const insertion of GS_INSERTION_EFFECT_LIST)
            this.registerInsertionProcessor(insertion);
        this.resetGSInsertionParams(); // Initial setup

        // Initialize voices
        this.allocateNewVoices(this.systemParameters.voiceCap);

        for (let i = 0; i < 16; i++) {
            // Don't send events as we're creating the initial channels
            this.createMIDIChannelInternal(false);
        }
        void this.ready.then(() => {
            SpessaLog.info("%cSpessaSynth is ready!", ConsoleColors.recognized);
        });
    }

